<script setup lang="ts">
import { computed, watch } from 'vue';
import { useRoute } from 'vue-router';
import { Refresh } from '@element-plus/icons-vue';
import { api } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { formatFen, shanghaiTime } from '../domain/m1';
import ErrorPanel from '../components/ErrorPanel.vue';
import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();
const {data,loading,error,load}=useRemote(async()=>{
  if(route.path.startsWith('/purchase-intents/')){const intent=await api.getIntent(String(route.params.id));return {intent,purchase:intent.purchaseOrderId?await api.getPurchase(intent.purchaseOrderId):null};}
  const purchase=await api.getPurchase(String(route.params.id));return {purchase,intent:await api.getIntent(purchase.purchaseIntentId)};
});
const state=computed(()=>data.value?.purchase?.state??data.value?.intent.state);const unknown=computed(()=>state.value==='CREATE_UNKNOWN');
watch(()=>route.fullPath,()=>void load(),{immediate:true});
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">采购管理 / 详情</p><h1>{{ route.path.startsWith('/purchase-intents/')?'采购意图详情':'采购订单详情' }}</h1><p class="muted">Mock / 待授权 · 采购、支付记录独立 · 本阶段未实现付款</p></div><div class="inline-actions"><RouterLink class="text-link" to="/purchases">返回采购管理</RouterLink><el-button :icon="Refresh" :loading="loading" @click="load">刷新状态</el-button></div></div><div v-if="loading" class="panel data-state" role="status"><el-skeleton :rows="6" animated /><p>正在读取 Mock 采购状态…</p></div><ErrorPanel v-else-if="error" :error="error" :title="error.status===404?'采购记录不存在或不可见':'采购详情读取失败'"><el-button @click="load">重试</el-button></ErrorPanel><template v-else-if="data"><div v-if="unknown" class="freeze-note" role="status"><h2>创单结果未知，请勿重新下单</h2><p>后台按有限重试查询 Mock 权威状态；结果未明确前保持冻结。查询耗尽后需人工核对，本阶段不提供重新创单。</p></div><div v-else-if="state==='REVIEW_REQUIRED'" class="freeze-note" role="status"><h2>需要人工处理，请勿重新下单</h2><p>自动查询已停止或规则发生变化，请核验权威状态和阻塞原因。M2 不提供强制创单或支付入口。</p></div><section class="panel detail-panel"><div class="panel-heading"><div><h2>采购状态</h2><p>仅 Mock 权威创单成功后进入待付款，不代表真实平台交易。</p></div><StatusBadge v-if="state" :status="state" /></div><dl class="order-facts"><div><dt>采购意图 ID</dt><dd class="mono">{{ data.intent.id }}</dd></div><div><dt>采购订单 ID</dt><dd class="mono">{{ data.purchase?.id??'尚未创建 · 后台异步处理中' }}</dd></div><div><dt>采购金额 · CNY</dt><dd class="detail-money">{{ formatFen(data.purchase?.totalFen??data.intent.estimatedTotalFen) }}</dd></div><div><dt>Mock 外部采购单号</dt><dd class="mono">{{ data.purchase?.externalOrderId??'尚未取得权威单号' }}</dd></div><div><dt>销售子项 / 数量</dt><dd class="mono">{{ data.intent.salesOrderItemId }} / {{ data.intent.qty }}</dd></div><div><dt>付款状态</dt><dd>未付款 · 支付功能待 M3</dd></div><div><dt>创建时间（上海）</dt><dd>{{ shanghaiTime(data.intent.createdAt) }}</dd></div><div><dt>最后更新（上海）</dt><dd>{{ shanghaiTime(data.purchase?.updatedAt??data.intent.updatedAt) }}</dd></div><div><dt>意图 / 采购版本</dt><dd>{{ data.intent.version }} / {{ data.purchase?.version??'—' }}</dd></div></dl><RouterLink class="text-link" :to="`/orders/${data.intent.salesOrderId}`">查看关联销售订单</RouterLink></section><section v-if="data.intent.quote" class="panel detail-panel"><h2>创建时的报价快照</h2><dl class="order-facts"><div><dt>单价 / 数量</dt><dd>{{ formatFen(data.intent.quote.unitPriceFen) }} × {{ data.intent.quote.qty }}</dd></div><div><dt>运费 / 费用</dt><dd>{{ formatFen(data.intent.quote.shippingFen) }} / {{ formatFen(data.intent.quote.feeFen) }}</dd></div><div><dt>到手总价（CNY）</dt><dd>{{ formatFen(data.intent.quote.totalFen) }}</dd></div><div><dt>报价时间（上海）</dt><dd>{{ shanghaiTime(data.intent.quote.quotedAt) }}</dd></div><div><dt>报价有效至（上海）</dt><dd>{{ shanghaiTime(data.intent.quote.expiresAt) }}</dd></div><div><dt>货源版本 / 映射 ID</dt><dd class="mono">{{ data.intent.quote.offerVersion }} / {{ data.intent.mappingId }}</dd></div></dl><p class="help-text muted">后续映射与价格修改不会悄然覆盖此快照；创建前报价变化会阻塞。</p></section><section class="panel detail-panel"><h2>审核与阻塞原因</h2><p v-if="data.intent.failureCode" class="help-text">{{ data.intent.failureCode }}</p><ul v-if="data.intent.reasons.length" class="reason-list"><li v-for="reason in data.intent.reasons" :key="reason.code"><strong>{{ reason.code }}</strong> {{ reason.message }}</li></ul><p v-else class="help-text muted">暂无额外阻塞原因。后续状态由后台 Worker 处理，可刷新查看。</p></section></template></div></template>
